import{_ as i,o as a,c as s,a0 as t}from"./chunks/framework.BZ80FTt7.js";const k=JSON.parse('{"title":"2026-07-17：C++ 从封装走到 STL","description":"","frontmatter":{},"headers":[],"relativePath":"blog/2026-07-17-cpp-lessons-06-08.md","filePath":"blog/2026-07-17-cpp-lessons-06-08.md"}'),o={name:"blog/2026-07-17-cpp-lessons-06-08.md"};function d(l,e,p,c,n,h){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="_2026-07-17-c-从封装走到-stl" tabindex="-1">2026-07-17：C++ 从封装走到 STL <a class="header-anchor" href="#_2026-07-17-c-从封装走到-stl" aria-label="Permalink to &quot;2026-07-17：C++ 从封装走到 STL&quot;">​</a></h1><p>今天把第 06 课和第 07 课的练习全部跑通，又完整读完了第 08 课的 STL 讲义。进度不算快，但每一课都用同一条命令编译和测试：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g++ -std=c++20 -Wall -Wextra -Werror</span></span></code></pre></div><p>这次留下的东西比“多认识几个关键字”更具体：对象该把什么状态藏起来，引用成员为什么必须在创建时绑定，以及看到一个容器时该怎样选。</p><h2 id="第-06-课-对象要自己守住规则" tabindex="-1">第 06 课：对象要自己守住规则 <a class="header-anchor" href="#第-06-课-对象要自己守住规则" aria-label="Permalink to &quot;第 06 课：对象要自己守住规则&quot;">​</a></h2><p><code>Point</code>、<code>BankAccount</code> 和 <code>RunningMax</code> 这几个练习看起来很小，实际在练同一件事：把数据和操作数据的函数放在一起。</p><p><code>BankAccount</code> 最能说明问题。余额不能为负不是一句注释，而是对象始终要保持的规则。把 <code>balance_</code> 放在 <code>private</code> 里，再让 <code>deposit</code> 和 <code>withdraw</code> 成为仅有的修改入口，检查就集中在类内部。调用方不需要记住所有边界，账户自己负责不让状态跑偏。</p><p>这节还把几个常见写法放到实际代码里：</p><ul><li><code>int x{0}</code> 是花括号初始化，给成员一个明确默认值。</li><li><code>int value() const</code> 末尾的 <code>const</code> 表示这个函数只读当前对象。</li><li>单参数构造函数前的 <code>explicit</code> 阻止整数之类的值悄悄转换成对象。</li><li>函数参数和成员变量不是一回事。构造函数处理完 <code>initial</code> 后，仍要把结果保存到 <code>balance_</code>。</li></ul><p>这里最容易发生的不是语法错误，而是状态错误：局部变量看起来已经改对了，对象离开函数后却没有记住结果。以后写类时，得先分清“这行代码在改临时数据”还是“它在改对象状态”。</p><h2 id="第-07-课-让作用域负责收尾" tabindex="-1">第 07 课：让作用域负责收尾 <a class="header-anchor" href="#第-07-课-让作用域负责收尾" aria-label="Permalink to &quot;第 07 课：让作用域负责收尾&quot;">​</a></h2><p>第 07 课从构造函数、析构函数进入 RAII。它的直觉并不复杂：对象创建时完成初始化，对象离开作用域时自动清理。</p><p><code>ScopedCounter</code> 是一个很小的例子。构造时让外部计数器加一，析构时减一。外层和内层代码块结束后，计数自然回落，不需要在每个出口手动补一行“减一”。文件、锁、动态资源的管理以后都能用同样的思路处理。</p><p>今天第一次认真碰到 <code>= delete</code>：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ScopedCounter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ScopedCounter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ScopedCounter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> operator</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ScopedCounter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>它不是运行时判断，而是直接告诉编译器：这个类不能复制。这样一旦尝试复制作用域计数器，代码在编译阶段就会被拦住。一个对象承担唯一的清理责任时，这比事后排查“为什么多减了一次”可靠得多。</p><p>另一个要记住的点是引用成员：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> counter_;</span></span></code></pre></div><p>引用不是可以先空着的普通变量。它必须在构造时通过成员初始化列表绑定到一个对象，之后不能改绑。<code>counter_</code> 在这里不是保存一份数字，而是外部 <code>counter</code> 的别名。</p><h2 id="第-08-课-先学会选择容器" tabindex="-1">第 08 课：先学会选择容器 <a class="header-anchor" href="#第-08-课-先学会选择容器" aria-label="Permalink to &quot;第 08 课：先学会选择容器&quot;">​</a></h2><p>今天第 08 课只读完讲义，练习还没有开始。比起急着套模板，我先把容器按使用场景重新整理了一遍：</p><ul><li>顺序保存、按下标访问、需要排序时，用 <code>vector</code>。</li><li>按键统计或查找时，用 <code>unordered_map</code>；词频统计正是这个场景。</li><li>既要按键查找又要按键顺序遍历时，用 <code>map</code>。</li><li>只关心元素是否出现过时，用 <code>set</code> 或 <code>unordered_set</code>。</li><li>先进先出是 <code>queue</code>，后进先出是 <code>stack</code>，反复取当前最大值是 <code>priority_queue</code>。</li></ul><p><code>unordered_map</code> 有一个容易忽略的细节：<code>counts[word]</code> 在键不存在时会自动插入默认值。这对计数很方便，但如果只是查询是否存在，应该用 <code>find</code>，避免无意中把新键塞进表里。它的遍历顺序也不稳定，所以词频项目需要把结果放进 <code>vector</code>，再按“频率降序、同频词典序升序”排序。</p><h2 id="给后续学习留下的约定" tabindex="-1">给后续学习留下的约定 <a class="header-anchor" href="#给后续学习留下的约定" aria-label="Permalink to &quot;给后续学习留下的约定&quot;">​</a></h2><p>今天把跟学课堂的材料也调整了一下。每完成一课，练习文件末尾都会补两部分记录：</p><ul><li>本课真正学到的概念；</li><li>可迁移到其他代码的踩坑场景，例如“局部变量与对象状态混淆”“分支没有覆盖所有路径”。</li></ul><p>下一课的练习则提前写清楚每个函数的输入、输出、边界条件，以及新语法出现的原因。这样下次回看时，不用靠记忆猜题目想让我做什么。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>[ ] 完成第 08 课的四个 STL 练习并跑通测试。</li><li>[ ] 周末做第 08.5 课：文本词频 Top K 项目。</li><li>[ ] 项目会用 <code>unordered_map</code> 计数、<code>vector</code> 加 <code>sort</code> 排出前 K 个词，并处理空输入和同频排序。</li></ul><p>今天到这里。STL 的内容还没变成熟练度，但容器、算法和后面的词频项目已经连成了一条线。</p>`,30)])])}const u=i(o,[["render",d]]);export{k as __pageData,u as default};
